const makeReference = (seed: EventSeed, displayRu: string): ScriptureReference => {
  const match = passagePattern.exec(displayRu);
  const book = match ? referenceBookByAbbreviation[match[1]] : undefined;
  return {
    testament: seed.testament,
    bookId: book?.bookId ?? seed.bookId,
    bookRu: book?.bookRu ?? seed.bookRu,
    chapterStart: match ? Number(match[2]) : seed.chapter,
    verseStart: match ? Number(match[3]) : seed.verse,
    chapterEnd: match?.[4] ? Number(match[4]) : undefined,
    verseEnd: match?.[5] ? Number(match[5]) : undefined,
    displayRu,
  };
};

const makeEvent = (seed: EventSeed): BibleEvent => ({
  id: seed.id,
  slug: seed.id,
  titleRu: seed.title,
  scriptureSummary: seed.summary,
  historicalNote: seed.historicalNote,
  traditionNote: seed.traditionNote,
  evidenceType: seed.evidence ?? "scripture_explicit",
  testament: seed.testament,
  category: [seed.stories?.[0] ?? "библейская история"],
  importance: seed.importance ?? 3,
  chronology: {
    type: seed.type ?? (seed.year === undefined ? "relative" : "approximate"),
    startYear: seed.year,
    displayRu: seed.date ?? (seed.type === "relative" || seed.year === undefined ? "По ходу библейского повествования" : `около ${Math.abs(seed.year)} г. ${seed.year < 0 ? "до Р. Х." : "по Р. Х."}`),
    certainty: seed.certainty ?? (seed.year === undefined ? "low" : "medium"),
    noteRu: seed.year === undefined ? "Писание сообщает последовательность событий, но не даёт календарной даты." : "Год дан как ориентир для временной шкалы, а не как утверждение текста Писания.",
  },
  locations: (seed.locations ?? []).map((locationId, index, all) => ({
    locationId,
    role: locationId === (seed.mainLocation ?? auditedMainLocationByEventId[seed.id] ?? all[all.length - 1])
      ? "main"
      : index === 0
        ? "origin"
        : index === all.length - 1
          ? "destination"
          : "route_point",
    order: index + 1,
  })),
  characters: seed.characters ?? [],
  scriptureReferences: [seed.passage, ...(seed.parallelPassages ?? [])].map((passage) => makeReference(seed, passage)),
  storylineIds: seed.stories ?? [],
});

